using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InspectRigSeams {
 static string Key(Vector3 p)=>Mathf.RoundToInt(p.x*100000)+","+Mathf.RoundToInt(p.y*100000)+","+Mathf.RoundToInt(p.z*100000);
 static Dictionary<int,float> Weights(BoneWeight b){var d=new Dictionary<int,float>();foreach(var pair in new[]{(b.boneIndex0,b.weight0),(b.boneIndex1,b.weight1),(b.boneIndex2,b.weight2),(b.boneIndex3,b.weight3)})if(pair.Item2>0)d[pair.Item1]=d.GetValueOrDefault(pair.Item1)+pair.Item2;return d;}
 public static object Main(){var rows=new List<object>();foreach(var id in new[]{"CH01","CH02","CH03","CH04R","CH05","CH06R","CH07","CH08","CH09","CH10"}){var g=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/"+id+"/body.fbx");foreach(var r in g.GetComponentsInChildren<SkinnedMeshRenderer>()){var m=r.sharedMesh;var v=m.vertices;var bw=m.boneWeights;var groups=Enumerable.Range(0,v.Length).GroupBy(i=>Key(v[i])).Where(g=>g.Count()>1).ToArray();int mismatch=0;float max=0;foreach(var group in groups){var a=Weights(bw[group.First()]);foreach(var i in group.Skip(1)){var b=Weights(bw[i]);var delta=a.Keys.Union(b.Keys).Sum(k=>Mathf.Abs(a.GetValueOrDefault(k)-b.GetValueOrDefault(k)));if(delta>.0001f)mismatch++;max=Mathf.Max(max,delta);}}rows.Add(new{id,vertices=v.Length,boneWeights=bw.Length,duplicateGroups=groups.Length,mismatchedSeamVertices=mismatch,maxWeightDifference=max,skinQuality=r.quality.ToString(),projectSkinWeights=QualitySettings.skinWeights.ToString()});}}return new{items=rows};}
}
